SOURCE_INPUTS={'hive': {'asset_id': 'village-beehive-01', 'sha256': 'b9e0d06045977e88a0650ceaf73206366b78e313a7b73156dabae456e1705285', 'compressed': ''}, 'table': {'asset_id': 'interior-open-worktable-01', 'sha256': 'b4880f9c24dda10b566fa215c394295b6522a8ad448486918c591826480c09d8', 'compressed': ''}, 'frame': {'asset_id': 'beekeeping-recessed-comb-frame-01', 'sha256': '4744ff1a5e03d285792ceb8b838ae8cb81536e3fb968652f320de6cfb3badb7e', 'compressed': ''}}
